st.markdown(CSS, unsafe_allow_html=True)

PLOTLY_TEMPLATE = "simple_white"
FONT = dict(family="IBM Plex Sans, sans-serif", color=NAVY)
YEAR_COLORS = {"2025": TEAL, "2026": AMBER}
PCT_AXIS = dict(ticksuffix="%", tickformat=".2f")  # every rate axis: "%" suffix, 2 decimals


def style_fig(fig, height=420, legend_bottom=False, show_legend=True):
    """Apply one consistent look to every chart in the report."""
    layout_kwargs = dict(
        template=PLOTLY_TEMPLATE,
        font=FONT,
        title_font=dict(size=15, color=NAVY),
        height=height,
        margin=dict(t=60, l=10, r=10, b=10),
        plot_bgcolor="white",
        paper_bgcolor="white",
        legend_title_font=dict(size=12),
        showlegend=show_legend,
    )
    if legend_bottom:
        layout_kwargs["legend"] = dict(orientation="h", yanchor="top", y=-0.18, xanchor="center", x=0.5)
        layout_kwargs["margin"] = dict(t=60, l=10, r=10, b=55)
    fig.update_layout(**layout_kwargs)
    fig.update_xaxes(showgrid=False, linecolor="#D8DEE2")
    fig.update_yaxes(showgrid=True, gridcolor="#EDF1F3", linecolor="#D8DEE2")
    return fig


def fit_line(x, y):
    """
    Manual linear trendline (avoids requiring the optional `statsmodels`
    package that Plotly's built-in trendline="ols" needs).
    Returns (x_line, y_line, slope, r_value).
    """
    mask = (~pd.isna(x)) & (~pd.isna(y))
    x, y = np.asarray(x[mask], dtype=float), np.asarray(y[mask], dtype=float)
    if len(x) < 3 or np.std(x) == 0:
        return None, None, None, None
    slope, intercept = np.polyfit(x, y, 1)
    x_line = np.linspace(x.min(), x.max(), 50)
    y_line = slope * x_line + intercept
    r_value = np.corrcoef(x, y)[0, 1]
    return x_line, y_line, slope, r_value


def pct(value) -> str:
    """Format a rate as a string with exactly 2 decimals and a % sign."""
    return f"{value:.2f}%"


TIER_ORDER = ["Low volume", "Medium volume", "High volume"]


def volume_tier(sends: pd.Series) -> pd.Series:
    """Split campaigns into Low/Medium/High send-volume tiers (terciles)."""
    try:
        return pd.qcut(sends, 3, labels=["Low volume", "Medium volume", "High volume"], duplicates="drop")
    except ValueError:
        return pd.Series(["All campaigns"] * len(sends), index=sends.index)


# ----------------------------------------------------------------------
# HEADER
# ----------------------------------------------------------------------
HEADER_HTML = """
<div class="report-header">
<h1>D2C Email Performance</h1>
<p>Packs &middot; Online Marketplace &middot; Homeboost &mdash; 2025 vs 2026</p>
</div>
"""
st.markdown(HEADER_HTML, unsafe_allow_html=True)

tab_overview, tab_reasons = st.tabs(["Email Performance", "Unsubscribe Reasons"])

# ========================================================================
# TAB 1: EMAIL PERFORMANCE (unchanged from the prior version)
# ========================================================================
with tab_overview:

    @st.cache_data
    def load_data(file) -> pd.DataFrame:
        df = pd.read_csv(file, encoding="utf-8-sig")
        df.columns = [c.strip() for c in df.columns]

        df["Sent Date"] = pd.to_datetime(df["Sent Date"], errors="coerce")
        df["Year"] = df["Sent Date"].dt.year

        numeric_cols = ["Emails Sent", "Unique Opens", "Unique clicks", "Bounces", "Unsubscribes"]
        for col in numeric_cols:
            if col in df.columns:
                df[col] = pd.to_numeric(df[col], errors="coerce").fillna(0)

        # Use the file's own rate columns as-is — no recalculation from raw counts
        df["Open Rate"] = pd.to_numeric(df["Open Rate"], errors="coerce")
        df["Unsubscribe Rate"] = pd.to_numeric(df["Unsubscribe Rate"], errors="coerce")
        return df

    def year_summary(df: pd.DataFrame) -> pd.DataFrame:
        # Volume-weighted rates: sum unsubs/opens across all campaigns first,
        # THEN divide by total sends — so a 180,000-recipient launch counts
        # proportionally more than a 100-recipient test send, instead of each
        # campaign's rate counting equally regardless of size.
        grouped = df.groupby("Year").agg(
            Campaigns=("Campaign Name", "count"),
            Sends=("Emails Sent", "sum"),
            Opens=("Unique Opens", "sum"),
            Unsubs=("Unsubscribes", "sum"),
        ).reset_index()
        grouped["Open Rate %"] = (grouped["Opens"] / grouped["Sends"] * 100).round(2)
        grouped["Unsub Rate %"] = (grouped["Unsubs"] / grouped["Sends"] * 100).round(2)
        return grouped

    with st.expander("Data source", expanded=False):
        uploaded = st.file_uploader("Upload a different CSV", type=["csv"])
        st.caption(f"Defaults to **{DEFAULT_FILE}** in this folder if nothing is uploaded.")

    try:
        source = uploaded if uploaded is not None else DEFAULT_FILE
        df = load_data(source)
    except FileNotFoundError:
        st.error(
            f"Couldn't find **{DEFAULT_FILE}** in this folder. "
            "Either place the CSV next to this script, or upload it above."
        )
        st.stop()

    years_available = sorted(y for y in df["Year"].dropna().unique() if y in (2025, 2026))
    if not years_available:
        st.warning("No rows found with Sent Date in 2025 or 2026 — check the date column in your file.")
    years_available = years_available or sorted(df["Year"].dropna().unique())

    max_send = int(df["Emails Sent"].max()) if len(df) else 0
    all_campaign_names = sorted(df["Campaign Name"].dropna().unique())

    f1, f2, f3 = st.columns([1, 1.3, 2])
    with f1:
        selected_years = st.multiselect("Years", options=years_available, default=years_available)
    with f2:
        min_sends_filter = st.number_input(
            "Minimum emails sent (per campaign)",
            min_value=0, max_value=max_send if max_send else 0, value=0, step=1000,
            help="Filter out small test sends if needed.",
        )
    with f3:
        selected_campaigns = st.multiselect(
            "Campaign(s)", options=all_campaign_names,
            default=[], placeholder="All campaigns (choose one or more to narrow down)",
        )

    ytd_only = st.checkbox(
        "Limit every year to Jan – Sep only (year-to-date)",
        value=False,
        help="2026 isn't a complete year yet, so comparing it to a full 12 months of 2025 "
             "isn't apples-to-apples. Check this to cap every selected year at the same "
             "Jan–Sep window for a fair comparison.",
    )

    filtered = df[df["Year"].isin(selected_years) & (df["Emails Sent"] >= min_sends_filter)]
    if selected_campaigns:
        filtered = filtered[filtered["Campaign Name"].isin(selected_campaigns)]
    if ytd_only:
        filtered = filtered[filtered["Sent Date"].dt.month <= 9]

    summary = year_summary(filtered).set_index("Year")

    st.markdown('<hr class="section-divider" style="margin-top:0.6rem;">', unsafe_allow_html=True)

    # ------------------------------------------------------------------
    # TOP-LINE METRICS
    # ------------------------------------------------------------------
    st.subheader("2025 vs 2026 at a glance")

    open_delta = unsub_delta = campaigns_delta_pct = sends_delta_pct = unsubs_delta_pct = None
    if 2025 in summary.index and 2026 in summary.index:
        open_delta = round(summary.loc[2026, "Open Rate %"] - summary.loc[2025, "Open Rate %"], 2)
        unsub_delta = round(summary.loc[2026, "Unsub Rate %"] - summary.loc[2025, "Unsub Rate %"], 2)
        campaigns_delta_pct = (summary.loc[2026, "Campaigns"] - summary.loc[2025, "Campaigns"]) / summary.loc[2025, "Campaigns"] * 100
        sends_delta_pct = (summary.loc[2026, "Sends"] - summary.loc[2025, "Sends"]) / summary.loc[2025, "Sends"] * 100
        unsubs_delta_pct = (summary.loc[2026, "Unsubs"] - summary.loc[2025, "Unsubs"]) / summary.loc[2025, "Unsubs"] * 100 if summary.loc[2025, "Unsubs"] else 0

    for yr in sorted(selected_years):
        if yr not in summary.index:
            continue
        row = summary.loc[yr]
        st.markdown(f'<div class="year-label">{int(yr)}</div>', unsafe_allow_html=True)
        c1, c2, c3, c4, c5 = st.columns(5)

        is_2026 = (yr == 2026 and 2025 in summary.index)
        with c1:
            st.metric(
                "Campaigns sent", f"{int(row['Campaigns']):,}",
                delta=f"{campaigns_delta_pct:+.2f}% vs 2025" if is_2026 else None,
                delta_color="off",
            )
        with c2:
            st.metric(
                "Total emails sent", f"{int(row['Sends']):,}",
                delta=f"{sends_delta_pct:+.2f}% vs 2025" if is_2026 else None,
                delta_color="off",
            )
        with c3:
            st.metric(
                "Open rate", pct(row["Open Rate %"]),
                delta=f"{open_delta:+.2f} pts vs 2025" if is_2026 else None,
                delta_color="normal",
            )
        with c4:
            st.metric(
                "Unsubscribe rate", pct(row["Unsub Rate %"]),
                delta=f"{unsub_delta:+.2f} pts vs 2025" if is_2026 else None,
                delta_color="inverse",
            )
        with c5:
            st.metric(
                "Total unsubscribes", f"{int(row['Unsubs']):,}",
                delta=f"{unsubs_delta_pct:+.2f}% vs 2025" if is_2026 else None,
                delta_color="inverse",
            )

    if 2025 in summary.index and 2026 in summary.index:
        y25, y26 = summary.loc[2025], summary.loc[2026]
        direction = "more" if sends_delta_pct > 0 else "fewer"
        open_word = "improved" if open_delta > 0 else "declined"
        unsub_word = "rose" if unsub_delta > 0 else "fell"

        takeaway_html = f"""
<div class="callout">📌 <b>Takeaway:</b> D2C sent <b>{abs(sends_delta_pct):.2f}% {direction}</b>
emails in 2026 vs 2025. Over that same period, the open rate <b>{open_word}</b>
({pct(y25["Open Rate %"])} &rarr; {pct(y26["Open Rate %"])}), while the unsubscribe rate
<b>{unsub_word}</b> ({pct(y25["Unsub Rate %"])} &rarr; {pct(y26["Unsub Rate %"])}).</div>
"""
        st.markdown(takeaway_html, unsafe_allow_html=True)

    st.markdown('<hr class="section-divider">', unsafe_allow_html=True)

    # ------------------------------------------------------------------
    # SIMPLE MONTHLY COUNTS
    # ------------------------------------------------------------------
    st.subheader("Emails sent and unsubscribers, by month")

    monthly_counts_src = filtered.dropna(subset=["Sent Date"]).copy()
    monthly_counts_src["Month"] = monthly_counts_src["Sent Date"].dt.to_period("M").dt.to_timestamp()
    monthly_counts = monthly_counts_src.groupby("Month").agg(
        **{"Emails Sent": ("Emails Sent", "sum")},
        **{"Unique Opens": ("Unique Opens", "sum")},
        **{"Unsubscribers": ("Unsubscribes", "sum")},
    ).reset_index()

    if len(monthly_counts) > 0:
        fig_counts = go.Figure()
        fig_counts.add_trace(go.Bar(
            x=monthly_counts["Month"], y=monthly_counts["Emails Sent"],
            name="Emails sent", marker_color=TEAL, opacity=0.85, yaxis="y1",
        ))
        fig_counts.add_trace(go.Scatter(
            x=monthly_counts["Month"], y=monthly_counts["Unsubscribers"],
            name="Unsubscribers", mode="lines+markers",
            line=dict(color=AMBER, width=2.5), yaxis="y2",
        ))
        fig_counts.update_layout(
            title="Emails sent and unsubscribers per month",
            yaxis=dict(title="Emails sent", tickformat=",.0f"),
            yaxis2=dict(title="Unsubscribers", overlaying="y", side="right", showgrid=False, tickformat=",.0f"),
        )
        st.plotly_chart(style_fig(fig_counts, height=420, legend_bottom=True), use_container_width=True)

        fig_opens_counts = go.Figure()
        fig_opens_counts.add_trace(go.Bar(
            x=monthly_counts["Month"], y=monthly_counts["Unique Opens"],
            name="Email opens", marker_color=TURQUOISE, opacity=0.9, yaxis="y1",
        ))
        fig_opens_counts.add_trace(go.Scatter(
            x=monthly_counts["Month"], y=monthly_counts["Unsubscribers"],
            name="Unsubscribers", mode="lines+markers",
            line=dict(color=AMBER, width=2.5), yaxis="y2",
        ))
        fig_opens_counts.update_layout(
            title="Email opens and unsubscribers per month",
            yaxis=dict(title="Email opens", tickformat=",.0f"),
            yaxis2=dict(title="Unsubscribers", overlaying="y", side="right", showgrid=False, tickformat=",.0f"),
        )
        st.plotly_chart(style_fig(fig_opens_counts, height=420, legend_bottom=True), use_container_width=True)
    else:
        st.info("Not enough data in the current filter to show monthly counts.")

    st.markdown('<hr class="section-divider">', unsafe_allow_html=True)

    # ------------------------------------------------------------------
    # CORE ARGUMENT: does sending more actually help?
    # ------------------------------------------------------------------
    st.subheader("Does sending more actually work better?")

    campaign_level = filtered[filtered["Emails Sent"] > 0].copy()

    if len(campaign_level) >= 6:
        campaign_level["Volume Tier"] = volume_tier(campaign_level["Emails Sent"])
        tier_summary = campaign_level.groupby("Volume Tier", observed=True).agg(
            **{"Avg. Emails Sent": ("Emails Sent", "mean")},
            **{"Min Emails Sent": ("Emails Sent", "min")},
            **{"Max Emails Sent": ("Emails Sent", "max")},
            Sends=("Emails Sent", "sum"),
            Opens=("Unique Opens", "sum"),
            Unsubs=("Unsubscribes", "sum"),
            Campaigns=("Campaign Name", "count"),
        ).reset_index()
        tier_summary["Open Rate %"] = (tier_summary["Opens"] / tier_summary["Sends"] * 100).round(2)
        tier_summary["Unsub Rate %"] = (tier_summary["Unsubs"] / tier_summary["Sends"] * 100).round(2)
        tier_summary["Volume Tier"] = pd.Categorical(tier_summary["Volume Tier"], categories=TIER_ORDER, ordered=True)
        tier_summary = tier_summary.sort_values("Volume Tier")

        st.markdown("**Average emails sent, open rate, and unsubscribe rate — by send-size tier**")

        st.markdown(
            '<div class="legend-box">ℹ️ Campaigns in the current filter are split into 3 '
            '<b>equal-sized groups by count</b> (not equal-sized send ranges) based on '
            '<b>Emails Sent</b>: the smallest third of campaigns = <b>Low volume</b>, the '
            'middle third = <b>Medium volume</b>, the largest third = <b>High volume</b>. '
            'The exact cutoffs depend on whatever campaigns are currently in the filter — '
            'see the table below for the actual send-size range in each tier right now.</div>',
            unsafe_allow_html=True,
        )

        t1, t2, t3 = st.columns(3)

        with t1:
            fig_sends = px.bar(
                tier_summary, x="Volume Tier", y="Avg. Emails Sent",
                title="Avg. emails sent", color_discrete_sequence=[NAVY],
            )
            fig_sends.update_yaxes(tickformat=",.0f")
            st.plotly_chart(style_fig(fig_sends, height=340, show_legend=False), use_container_width=True)

        with t2:
            fig_open = px.bar(
                tier_summary, x="Volume Tier", y="Open Rate %",
                title="Avg. open rate", color_discrete_sequence=[TEAL],
            )
            fig_open.update_yaxes(**PCT_AXIS)
            st.plotly_chart(style_fig(fig_open, height=340, show_legend=False), use_container_width=True)

        with t3:
            fig_unsub = px.bar(
                tier_summary, x="Volume Tier", y="Unsub Rate %",
                title="Avg. unsubscribe rate", color_discrete_sequence=[LIGHT_BLUE],
            )
            fig_unsub.update_yaxes(**PCT_AXIS)
            st.plotly_chart(style_fig(fig_unsub, height=340, show_legend=False), use_container_width=True)

        boundary_table = tier_summary[["Volume Tier", "Campaigns", "Min Emails Sent",
                                        "Max Emails Sent", "Avg. Emails Sent",
                                        "Open Rate %", "Unsub Rate %"]].copy()
        boundary_table = boundary_table.rename(columns={
            "Min Emails Sent": "Smallest send in tier",
            "Max Emails Sent": "Largest send in tier",
            "Avg. Emails Sent": "Avg. emails sent",
        })
        for c in ["Smallest send in tier", "Largest send in tier", "Avg. emails sent"]:
            boundary_table[c] = boundary_table[c].round(0).astype(int).map("{:,}".format)
        boundary_table["Open Rate %"] = boundary_table["Open Rate %"].map(pct)
        boundary_table["Unsub Rate %"] = boundary_table["Unsub Rate %"].map(pct)
        st.dataframe(boundary_table, use_container_width=True, hide_index=True)

        best_open_tier = tier_summary.loc[tier_summary["Open Rate %"].idxmax(), "Volume Tier"]
        best_unsub_tier = tier_summary.loc[tier_summary["Unsub Rate %"].idxmin(), "Volume Tier"]
        same_tier_and_high = (best_open_tier == best_unsub_tier) and (best_open_tier == "High volume")
        st.markdown(
            f'<div class="insight">💡 The <b>{best_open_tier}</b> tier has the highest average open rate, '
            f'and the <b>{best_unsub_tier}</b> tier has the lowest average unsubscribe rate. '
            f'{"These are the same tier, which would support sending more." if same_tier_and_high else "The highest-volume tier is not the strongest performer on both measures, which does not support sending more as a strategy on its own."}</div>',
            unsafe_allow_html=True,
        )
    else:
        st.info("Not enough campaigns in the current filter to build volume tiers.")

    st.markdown('<hr class="section-divider">', unsafe_allow_html=True)

    # ------------------------------------------------------------------
    # SCATTER + TRENDLINE
    # ------------------------------------------------------------------
    st.subheader("Send size vs. performance, campaign by campaign")

    if len(campaign_level) >= 3:
        campaign_level["Year"] = campaign_level["Year"].astype(int).astype(str)

        col1, col2 = st.columns(2)

        with col1:
            x_line, y_line, slope, r = fit_line(campaign_level["Emails Sent"], campaign_level["Open Rate"])
            fig1 = px.scatter(
                campaign_level, x="Emails Sent", y="Open Rate", color="Year",
                hover_data=["Campaign Name"], color_discrete_map=YEAR_COLORS,
                category_orders={"Year": sorted(campaign_level["Year"].unique())},
            )
            fig1.update_traces(marker=dict(size=9, opacity=0.8, line=dict(width=0.5, color="white")))
            if x_line is not None:
                fig1.add_trace(go.Scatter(
                    x=x_line, y=y_line, mode="lines", name="Trend",
                    line=dict(color=NAVY, width=2, dash="dash"),
                ))
            fig1.update_layout(title="Send size vs. open rate", xaxis_title="Emails sent")
            fig1.update_yaxes(title="Open rate", **PCT_AXIS)
            st.plotly_chart(style_fig(fig1, height=400, legend_bottom=True), use_container_width=True)
            if slope is not None:
                slope_word = "essentially flat" if abs(r) < 0.15 else ("rises" if slope > 0 else "falls")
                st.caption(f"Trend line {slope_word} as send size increases (r = {r:.2f}).")

        with col2:
            x_line2, y_line2, slope2, r2 = fit_line(campaign_level["Emails Sent"], campaign_level["Unsubscribe Rate"])
            fig2 = px.scatter(
                campaign_level, x="Emails Sent", y="Unsubscribe Rate", color="Year",
                hover_data=["Campaign Name"], color_discrete_map=YEAR_COLORS,
                category_orders={"Year": sorted(campaign_level["Year"].unique())},
            )
            fig2.update_traces(marker=dict(size=9, opacity=0.8, line=dict(width=0.5, color="white")))
            if x_line2 is not None:
                fig2.add_trace(go.Scatter(
                    x=x_line2, y=y_line2, mode="lines", name="Trend",
                    line=dict(color=NAVY, width=2, dash="dash"),
                ))
            fig2.update_layout(title="Send size vs. unsubscribe rate", xaxis_title="Emails sent")
            fig2.update_yaxes(title="Unsubscribe rate", **PCT_AXIS)
            st.plotly_chart(style_fig(fig2, height=400, legend_bottom=True), use_container_width=True)
            if slope2 is not None:
                slope_word2 = "essentially flat" if abs(r2) < 0.15 else ("rises" if slope2 > 0 else "falls")
                st.caption(f"Trend line {slope_word2} as send size increases (r = {r2:.2f}).")
    else:
        st.info("Not enough campaigns in the current filter to plot this relationship.")

    st.markdown('<hr class="section-divider">', unsafe_allow_html=True)

    # ------------------------------------------------------------------
    # MONTHLY VOLUME VS. RATES, DUAL-AXIS
    # ------------------------------------------------------------------
    st.subheader("Monthly send volume vs. performance")

    trend = filtered.dropna(subset=["Sent Date"]).copy()
    trend["Month"] = trend["Sent Date"].dt.to_period("M").dt.to_timestamp()
    monthly = trend.groupby("Month").agg(
        Sends=("Emails Sent", "sum"),
        **{"Open Rate %": ("Open Rate", "mean")},
        **{"Unsub Rate %": ("Unsubscribe Rate", "mean")},
    ).reset_index()

    if len(monthly) > 1:
        fig_dual = go.Figure()
        fig_dual.add_trace(go.Bar(
            x=monthly["Month"], y=monthly["Sends"], name="Emails sent",
            marker_color=TEAL, opacity=0.85, yaxis="y1",
        ))
        fig_dual.add_trace(go.Scatter(
            x=monthly["Month"], y=monthly["Open Rate %"], name="Open rate",
            mode="lines+markers", line=dict(color=GREEN, width=2.5), yaxis="y2",
        ))
        fig_dual.add_trace(go.Scatter(
            x=monthly["Month"], y=monthly["Unsub Rate %"], name="Unsubscribe rate",
            mode="lines+markers", line=dict(color=AMBER, width=2.5), yaxis="y2",
        ))
        fig_dual.update_layout(
            title="Emails sent per month vs. open & unsubscribe rate",
            yaxis=dict(title="Emails sent"),
            yaxis2=dict(title="Rate", overlaying="y", side="right", showgrid=False, **PCT_AXIS),
        )
        st.plotly_chart(style_fig(fig_dual, height=460, legend_bottom=True), use_container_width=True)

        vol_open_corr = monthly["Sends"].corr(monthly["Open Rate %"])
        vol_unsub_corr = monthly["Sends"].corr(monthly["Unsub Rate %"])
        st.markdown(
            f'<div class="insight">💡 Month-over-month, total send volume correlates with open rate at '
            f'<b>r = {vol_open_corr:.2f}</b> and with unsubscribe rate at <b>r = {vol_unsub_corr:.2f}</b>. '
            f'A correlation near zero means heavier-sending months are not reliably performing better '
            f'(or worse) — sending more, by itself, isn\'t moving these numbers in a consistent direction.</div>',
            unsafe_allow_html=True,
        )
    else:
        st.info("Not enough data across months to show a trend.")

    st.markdown('<hr class="section-divider">', unsafe_allow_html=True)

    # ------------------------------------------------------------------
    # CAMPAIGN-LEVEL DETAIL
    # ------------------------------------------------------------------
    st.subheader("Campaign-level detail")

    detail = filtered.copy().sort_values("Sent Date", ascending=False)
    detail_display = pd.DataFrame({
        "Campaign Name": detail["Campaign Name"],
        "Year": detail["Year"],
        "Sent Date": detail["Sent Date"],
        "Emails Sent": detail["Emails Sent"],
        "Unique Opens": detail["Unique Opens"],
        "Open Rate": detail["Open Rate"].map(pct),
        "Unsubscribes": detail["Unsubscribes"],
        "Unsubscribe Rate": detail["Unsubscribe Rate"].map(pct),
    })

    st.dataframe(detail_display, use_container_width=True, hide_index=True)
    st.caption(f"Showing {len(detail):,} of {len(filtered):,} campaigns in the current filter.")

# ========================================================================
# TAB 2: UNSUBSCRIBE REASONS
# One section per year, each built from a per-contact export of the single
# highest-unsubscribe campaign that year (e.g. an ActiveCampaign "who
# unsubscribed from this campaign" report, not the campaign-performance file).
# ========================================================================
with tab_reasons:
    st.subheader("Unsubscribe reasons — highest-unsubscribe campaign per year")
    st.caption("The 2025 and 2026 data below is embedded in this report — nothing to upload.")

    def load_reasons(embedded_b64):
        csv_bytes = base64.b64decode(embedded_b64)
        rdf = pd.read_csv(io.StringIO(csv_bytes.decode("utf-8")))

        rdf.columns = [c.strip() for c in rdf.columns]

        if "Details" in rdf.columns:
            rdf["Details"] = rdf["Details"].fillna("").astype(str).str.strip()
            rdf["Details"] = rdf["Details"].replace("", "No reason provided")
        else:
            rdf["Details"] = "No reason provided"

        rdf["Opens"] = pd.to_numeric(rdf.get("Opens", 0), errors="coerce").fillna(0)
        rdf["Clicks"] = pd.to_numeric(rdf.get("Clicks", 0), errors="coerce").fillna(0)
        rdf["Event Date"] = pd.to_datetime(rdf.get("Last opened"), errors="coerce")
        return rdf

    def render_year_reason_section(year, rdf, color):
        if rdf is None:
            st.info(f"No data available for {year}.")
            return

        campaign_name = "Unknown campaign"
        if "Campaign Name" in rdf.columns and rdf["Campaign Name"].notna().any():
            campaign_name = rdf["Campaign Name"].dropna().iloc[0]

        st.markdown(f"#### {year} &mdash; {campaign_name}")

        total_unsubs = len(rdf)
        avg_opens = rdf["Opens"].mean() if total_unsubs else 0
        pct_with_reason = (rdf["Details"] != "No reason provided").mean() * 100 if total_unsubs else 0

        m1, m2, m3 = st.columns(3)
        m1.metric("Total unsubscribes", f"{total_unsubs:,}")
        m2.metric("Avg. opens per unsubscriber", f"{avg_opens:.2f}")
        m3.metric("% who gave a reason", f"{pct_with_reason:.1f}%")

        reason_counts = rdf["Details"].value_counts().reset_index()
        reason_counts.columns = ["Reason", "Count"]
        reason_counts["Pct"] = reason_counts["Count"] / total_unsubs * 100
        reason_counts["Label"] = reason_counts["Pct"].map(lambda p: f"{p:.1f}%")

        fig_r = px.bar(
            reason_counts, x="Count", y="Reason", orientation="h",
            title=f"{year}: unsubscribe reasons", color_discrete_sequence=[color],
            text="Label",
        )
        fig_r.update_traces(textposition="inside", textfont_color="white", insidetextanchor="end")
        fig_r.update_layout(yaxis={"categoryorder": "total ascending"})
        st.plotly_chart(style_fig(fig_r, height=380, show_legend=False), use_container_width=True)

        with st.expander(f"See the raw {year} unsubscribe list"):
            show_cols = [c for c in ["First Name", "Last Name", "Email", "Opens", "Clicks",
                                      "Details", "Event Date"] if c in rdf.columns]
            st.dataframe(rdf[show_cols], use_container_width=True, hide_index=True)

    reasons_df_2025 = load_reasons(REASONS_EMBEDDED_2025_B64)
    reasons_df_2026 = load_reasons(REASONS_EMBEDDED_2026_B64)

    render_year_reason_section(2025, reasons_df_2025, TEAL)
    st.markdown('<hr class="section-divider">', unsafe_allow_html=True)
    render_year_reason_section(2026, reasons_df_2026, AMBER)